<script setup lang="ts">
import {ref} from 'vue'
type Scenario={fraction:number,net_up_points:number|null,sessions:number|null}
type RangeWindow={window:number,samples:number,required:number,start:string|null,end:string|null,ready:boolean,average_points:number|null,average_pct:number|null,amplitude_units:number|null,scenarios:Scenario[],reason:string}
type Index={symbol:string,title:string,as_of:string,close:number,ma20:number|null,above:boolean|null,distance_points:number|null,distance_pct:number|null,remaining_up_points:number|null,remaining_up_pct:number|null,next_close_threshold:number|null,next_required_up_points:number|null,ma_ready:boolean,ma_samples:number,range_windows:Record<string,RangeWindow>,warning?:string}
export type Ma20Data={available:boolean,as_of:string|null,indices:Index[],both_below:boolean|null,note:string,warnings:string[]}
defineProps<{data:Ma20Data}>()
const window=ref<5|20>(20)
const fmt=(v:number|null|undefined,d=2)=>v==null?'—':v.toLocaleString('zh-TW',{minimumFractionDigits:d,maximumFractionDigits:d})
const pct=(v:number|null|undefined)=>v==null?'—':`${v>0?'+':''}${fmt(v)}%`
const range=(row:Index)=>row.range_windows[String(window.value)]
const source=(row:Index)=>row.symbol==='TAIEX'?'https://www.twse.com.tw/indicesReport/MI_5MINS_HIST':'https://www.tpex.org.tw/zh-tw/mainboard/trading/info/index.html'
</script>
<template>
 <section class="ma20-observation">
  <div class="ma20-controls"><div><strong v-if="data.both_below===true" class="below">雙指數均低於20MA</strong><strong v-else-if="data.both_below===false" class="above">至少一個指數不低於20MA</strong><strong v-else>等待完整20MA資料</strong><p>雙指數濾網只在兩者都低於20MA時阻擋新增；任一站回即解除這一項限制。</p></div><div class="range-switch" role="group" aria-label="平均日振幅觀察期間"><button v-for="n in [5,20] as const" :key="n" :class="{active:window===n}" :aria-pressed="window===n" @click="window=n">近{{n}}日振幅</button></div></div>
  <p v-for="warning in data.warnings" :key="warning" class="ma20-warning">{{warning}}</p>
  <p v-if="!data.available" class="ma20-empty">請先完成加權與櫃買行情更新；不以缺漏資料推算天數。</p>
  <div v-else class="ma20-grid">
   <article v-for="row in data.indices" :key="row.symbol" class="index-distance" :data-index="row.symbol">
    <header><div><h3>{{row.title}}</h3><span>{{row.as_of}} 收盤 · <a :href="source(row)" target="_blank" rel="noopener noreferrer">來源日線 ↗</a></span></div><b :class="row.above===true?'above':row.above===false?'below':'muted'">{{row.above===true?'不低於20MA':row.above===false?'20MA下方':'資料不足'}}</b></header>
    <div class="ma20-quotes"><div><small>收盤指數</small><strong>{{fmt(row.close)}}</strong></div><div><small>20MA</small><strong>{{fmt(row.ma20)}}</strong></div><div><small>目前乖離</small><strong :class="row.above?'above':'below'">{{pct(row.distance_pct)}}</strong></div></div>
    <template v-if="row.ma_ready">
     <div class="ma20-gap" :class="row.above?'is-above':''"><small>{{row.above?'高於目前20MA':'回到目前20MA尚差'}}</small><strong>{{fmt(Math.abs(row.distance_points||0))}} <em>點</em></strong><span v-if="!row.above">需由目前收盤上漲 {{fmt(row.remaining_up_pct)}}%</span><span v-else>目前已達雙指數濾網的單邊門檻</span></div>
     <div class="next-threshold"><div><span>下一交易日不低於20MA的收盤門檻</span><strong>{{fmt(row.next_close_threshold)}} 點</strong></div><p v-if="(row.next_required_up_points||0)>0">相對本次收盤仍需上漲 <b>{{fmt(row.next_required_up_points)}} 點</b></p><p v-else>若下一交易日維持目前收盤，便不低於新的20MA。</p></div>
    </template>
    <p v-else class="ma20-warning">{{row.warning||`20MA收盤不足 ${row.ma_samples}/20`}}</p>
    <div class="range-summary"><div><span>近 {{window}} 日平均日振幅</span><strong>{{fmt(range(row).average_points)}} 點 <small>{{range(row).average_pct==null?'':`（${fmt(range(row).average_pct)}%）`}}</small></strong></div><small>{{range(row).samples}}／{{range(row).required}} 筆日K<br>{{range(row).start}}～{{range(row).end}}</small></div>
    <p v-if="!range(row).ready||range(row).average_points===0" class="ma20-warning">{{range(row).reason}}</p>
    <p v-if="row.ma_ready&&!row.above&&range(row).amplitude_units!=null" class="amplitude-units">距目前20MA，相當於 <b>{{fmt(range(row).amplitude_units,1)}}</b> 個平均日振幅；這是距離換算，不是到達天數。</p>
    <div class="scenario-title"><strong>粗估站回天數｜單向上漲情境</strong><span>每天淨漲固定，20MA同步滾動</span></div>
    <div class="ma20-scenarios"><div v-for="scenario in range(row).scenarios" :key="scenario.fraction"><small>每天淨漲 {{scenario.fraction===.5?'半個':'一個'}}平均振幅</small><strong v-if="scenario.sessions===0" class="above">目前已達門檻</strong><strong v-else-if="scenario.sessions!=null">約 {{scenario.sessions}} <em>個交易日</em></strong><strong v-else class="muted">無法估算</strong><span v-if="scenario.net_up_points!=null">假設每日淨上漲 {{fmt(scenario.net_up_points)}} 點</span></div></div>
   </article>
  </div>
  <details class="ma20-method"><summary>差距與天數怎麼算</summary><ul><li>20MA是最近20個交易日收盤的簡單平均；乖離＝（收盤÷20MA－1）×100%。「回到目前20MA需上漲%」則以目前收盤為分母。</li><li>下一交易日的20MA會剔除最舊一筆、納入新收盤。要使新收盤不低於新20MA，理論門檻是目前最後19筆收盤的平均；顯示門檻再依指數0.01點報價向上取整。</li><li>日振幅＝當日最高－最低；振幅%以該日前一交易日收盤為分母，再取所選5／20日平均。只用完整日K，不把單純收盤漲跌當成盤中振幅。</li><li>天數是假設每天都淨上漲半個／一個平均振幅，逐日加入假設收盤並重算20MA，找首次達到均線的交易日。</li></ul></details>
  <p class="ma20-disclaimer">振幅包含上下震盪，不代表每天都能向上推進。上述是條件式試算，沒有賦予發生機率；若盤整或下跌，實際可能更久或無法站回。盤中不使用當天未完成日K，不會因此更新任何策略持股。</p>
 </section>
</template>
<style scoped>
