ex;justify-content:space-between;gap:10px;flex-wrap:wrap}.next-threshold>div>span{color:#83917a}.next-threshold p{margin:6px 0;color:#8b9582;font-size:11px;line-height:1.7}.range-summary{display:flex;justify-content:space-between;gap:14px;border-top:1px solid #e9eee5;margin-top:17px;padding-top:16px}.range-summary span{display:block;font-size:12px;color:#87937d}.range-summary strong{display:block;margin-top:8px;font-size:19px}.range-summary strong small{font-size:11px;font-weight:400;color:#87937d}.range-summary>small{text-align:right;font-size:10px;color:#97a08f;line-height:1.9}.amplitude-units{font-size:11px;color:#89957f;line-height:1.8;margin:12px 0}.amplitude-units b{color:#597a65}.scenario-title{margin:19px 0 10px;display:flex;flex-wrap:wrap;gap:5px 12px;align-items:baseline}.scenario-title strong{font-size:12px}.scenario-title span{font-size:10px;color:#929c89}.ma20-scenarios{display:grid;grid-template-columns:1fr 1fr;gap:10px}.ma20-scenarios>div{padding:13px 12px;border-radius:8px;background:#f5f7f2;min-width:0}.ma20-scenarios small{font-size:10px;color:#819076}.ma20-scenarios strong{display:block;font-size:21px;margin:9px 0;color:#536f5b}.ma20-scenarios span{display:block;font-size:10px;color:#94a087;line-height:1.7}.ma20-warning{padding:9px 12px;background:#faf4e7;border-radius:7px;color:#997b42;font-size:11px;line-height:1.8}.ma20-empty{padding:20px;color:#929c87}.ma20-method{background:#f7f8f4;border-radius:9px;padding:13px 16px;margin-top:18px;font-size:12px;line-height:1.9;color:#809075}.ma20-method summary{cursor:pointer;font-weight:700}.ma20-method li{margin:7px 0}.ma20-disclaimer{font-size:11px;line-height:1.9;color:#8e9982;margin:13px 0 0}@media(max-width:1050px){.ma20-grid{grid-template-columns:1fr}}@media(max-width:650px){.ma20-observation{padding:0 14px 16px}.ma20-controls{align-items:flex-start;flex-direction:column}.index-distance{padding:15px}.ma20-quotes{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.ma20-quotes strong{font-size:18px}.ma20-quotes>div:last-child{grid-column:1/-1;display:flex;align-items:center;gap:12px}.ma20-quotes>div:last-child small{margin-bottom:0}.range-summary{flex-direction:column}.range-summary>small{text-align:left}.ma20-scenarios{grid-template-columns:1fr}.ma20-method{padding:12px}.index-distance header span{font-size:10px}}
